import * as T from 'three';
import {box} from './models.js';
// Fixed LED ring: only the illuminated sector and its projected beam travel.
export function installRotaryBeacons(model){const items=[];for(const lens of model.userData.beacons){if(lens.geometry.type!=='CylinderGeometry')continue;lens.material.transparent=true;lens.material.opacity=.38;lens.material.depthWrite=false;const ring=new T.Group();ring.position.copy(lens.position);model.add(ring);const leds=Array.from({length:16},(_,i)=>{const a=i*Math.PI*2/16,led=box(ring,.055,.12,.03,new T.MeshStandardMaterial({color:'#4c88b1',emissive:'#168aff',emissiveIntensity:0}),Math.sin(a)*.17,0,Math.cos(a)*.17);led.rotation.y=a;return led;});const rotor=new T.Group();rotor.position.copy(lens.position);model.add(rotor);const beam=new T.SpotLight('#258aff',0,22,.3,.65,1.4);beam.position.set(0,0,.13);const target=new T.Object3D();target.position.set(0,-1.8,6);rotor.add(beam,target);beam.target=target;beam.castShadow=false;beam.visible=false;items.push({lens,ring,leds,rotor,beam});}model.userData.rotaryBeacons=items;}
export function updateRotaryBeacons(model,enabled,seconds,camera){const items=model.userData.rotaryBeacons||[];for(const [i,b]of items.entries()){if(enabled)b.rotor.rotation.y=seconds*7+i*1.4;const angle=b.rotor.rotation.y;b.beam.intensity=enabled?160:0;b.beam.visible=!!enabled;b.leds.forEach((led,j)=>{const sector=j*Math.PI*2/b.leds.length;led.material.emissiveIntensity=enabled?12*Math.pow(Math.max(0,Math.cos(angle-sector)),12):0;});const view=Math.atan2(camera.x-model.position.x,camera.z-model.position.z)-model.rotation.y;const sweep=Math.pow(Math.max(0,Math.cos(angle-view)),14);b.lens.material.emissiveIntensity=enabled?.15+3*sweep:0;}return items.length>0;}
